import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
const catalog = JSON.parse(
  readFileSync(new URL("src/lib/data/research-catalog.json", root), "utf8"),
);
const quote = (value) => (value == null ? "NULL" : `'${String(value).replaceAll("'", "''")}'`);
const json = (value) => quote(JSON.stringify(value));
const now = "CAST(strftime('%s', 'now') AS INTEGER)";
const lines = [
  "-- Generated by node scripts/research-catalog.mjs; edit research-catalog.json instead.",
  `-- Dataset cards verified ${catalog.verifiedAt}. Registers metadata, not raw CSV rows.`,
  "-- Upserts the real catalog; preserves hypotheses, results, and user-submitted catalog entries.",
];

for (const ps of catalog.problemStatements) {
  lines.push(
    `INSERT INTO problem_statements (id, question, description, domain, hypothesis_count, created_at, updated_at) VALUES (${quote(ps.id)}, ${quote(ps.question)}, ${quote(ps.description)}, ${quote(ps.domain)}, 0, ${now}, ${now}) ON CONFLICT(id) DO UPDATE SET question=excluded.question, description=excluded.description, domain=excluded.domain, updated_at=excluded.updated_at;`,
  );
}

for (const ds of catalog.datasets) {
  const columns = [
    "id",
    "name",
    "huggingface_url",
    "task_description",
    "data_column_names",
    "target_column_name",
    "description",
    "domain",
    "osf_characterization",
    "license",
    "foreknowledge_status",
    "unit_of_analysis",
    "created_at",
    "updated_at",
  ];
  const values = [
    quote(ds.id),
    quote(ds.name),
    quote(ds.huggingfaceUrl),
    quote(ds.taskDescription),
    json(ds.dataColumnNames),
    quote(ds.targetColumnName),
    quote(ds.description),
    quote(ds.domain),
    json(ds.osfCharacterization),
    quote(ds.license),
    quote(ds.foreknowledgeStatus),
    quote(ds.unitOfAnalysis),
    Math.floor(Date.parse(ds.createdAt) / 1000),
    now,
  ];
  const updates = columns
    .filter((c) => !["id", "created_at"].includes(c))
    .map((c) => `${c}=excluded.${c}`);
  lines.push(
    `INSERT INTO datasets (${columns.join(", ")}) VALUES (${values.join(", ")}) ON CONFLICT(id) DO UPDATE SET ${updates.join(", ")};`,
    `INSERT INTO dataset_problem_statements (dataset_id, problem_statement_id) VALUES (${quote(ds.id)}, ${quote(ds.problemStatementId)}) ON CONFLICT DO NOTHING;`,
  );
}

// Only retire the exact original fixture questions, not arbitrary user entries.
// Hypotheses and experiments are intentionally left untouched (still mock data).
const retired = [
  ["ps-2", "What makes an image unforgettable?"],
  ["ps-3", "What drives opinion change in online debates?"],
  ["ps-4", "How does visual context affect memorability?"],
];
const fixture = (id, question) =>
  `id=${quote(id)} AND question=${quote(question)} AND created_at=1726358400`;
const oldCmv = fixture(...retired[1]);
lines.push(
  `INSERT INTO dataset_problem_statements (dataset_id, problem_statement_id) SELECT dataset_id, 'ps-1' FROM dataset_problem_statements WHERE problem_statement_id='ps-3' AND EXISTS (SELECT 1 FROM problem_statements WHERE ${oldCmv}) ON CONFLICT DO NOTHING;`,
);
for (const [id, question] of retired) {
  const predicate = fixture(id, question);
  lines.push(
    `DELETE FROM dataset_problem_statements WHERE problem_statement_id=${quote(id)} AND EXISTS (SELECT 1 FROM problem_statements WHERE ${predicate});`,
    `DELETE FROM problem_statements WHERE ${predicate};`,
  );
}
lines.push(
  "UPDATE problem_statements SET hypothesis_count=(SELECT count(*) FROM hypotheses WHERE hypotheses.problem_statement=problem_statements.question);",
);
const sql = `${lines.join("\n\n")}\n`;
const path = new URL("scripts/catalog.sql", root);
const seedPath = new URL("scripts/seed.sql", root);
if (process.argv.includes("--check")) {
  for (const target of [path, seedPath]) {
    if (readFileSync(target, "utf8") !== sql)
      throw new Error(`${fileURLToPath(target)} is stale; run node scripts/research-catalog.mjs`);
  }
} else {
  writeFileSync(path, sql);
  writeFileSync(seedPath, sql);
  console.log(`Generated ${fileURLToPath(path)}`);
}
